import Foundation

/// Single controls (buttons, menus, pickers) that have no entry of their own as a setting or a screen. Each one is what `.atlas("control....")` points at, so Show me can spotlight it.
/// Written from reading the code; `reviewed` stays false until someone has checked the wording on the running app.
enum AtlasControls {
    private static func c(_ id: String, _ title: String, _ summary: String, _ path: [String], all: Bool = false) -> AtlasEntry {
        .make(id, .control, title, summary, path: path, platforms: all ? .all : .mac, reviewed: checked.contains(id))
    }

