        c("control.settings.enhancementSponsorSkip", "Skip sponsor segments (page option)", "A switch under the one streaming service that offers it. Off by default. Turning it on first explains that the first 4 characters of a hash of each video's id are sent to a community service, and asks you to confirm. Skips show a short note with Undo. Never active in a kids profile or while the app is locked.", ["Settings", "Privacy", "Streaming services"]),
        c("control.settings.enhancementHideAds", "Hide ads and upgrade prompts (page option)", "A switch under Spotify. Off by default. Turning it on first spells out the risks and asks you to confirm: Spotify's terms prohibit blocking or circumventing its ads, it can lead to Spotify suspending or terminating your account, it is best effort and can stop working at any time, and Premium accounts see no ads. It hides ad boxes and upgrade prompts and stops the page contacting Spotify's ad servers, using a rule list on the Spotify page only. Takes effect the next time the page loads. Never active in a kids profile or while the app is locked.", ["Settings", "Privacy", "Streaming services"]),
        c("control.settings.enhancementMuteAds", "Mute audio ads (page option)", "A switch under Spotify. Off by default. Turning it on first spells out the same risks and asks you to confirm. It mutes the page's sound only while the player shows that an ad is playing and restores it afterwards; it never skips, speeds up or saves anything. Takes effect the next time the page loads. Never active in a kids profile or while the app is locked.", ["Settings", "Privacy", "Streaming services"]),
        c("control.settings.tidyPages", "Tidy pages (per service)", "A switch on each service's card in Settings, Privacy, Streaming services. Off by default. On hides banners and buttons that ask you to install the app, where StreamSetu knows a stable marker for them. It does not block ads and does not touch cookie questions, video or sign-in. Page layout can change at any time, so a banner may come back; Hide This Element is the fallback. Mac only.", ["Settings", "Privacy", "Streaming services"]),
        c("control.settings.hiddenElementsReset", "Reset hidden elements (per service)", "Shows 'Hidden elements: N' for a service and a Reset button that, after a confirmation, brings back every element you hid with Hide This Element on that service. Clear Data does not remove them. Mac only.", ["Settings", "Privacy", "Streaming services"]),
        c("control.settings.enhancementReload", "Reload to apply page options (Settings)", "Appears after a page option was changed. Reloads the open service so the change applies now; nothing reloads by itself.", ["Settings", "Privacy", "Streaming services"]),
        c("control.settings.enhancementPromptReset", "Show the first-open prompt again", "Makes the one-time card about page options appear again the next time that service is opened. It changes no option.", ["Settings", "Privacy", "Streaming services"]),
